def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    emit(g.copy(), "Input: a periodic wallpaper with several solid rectangles pasted over it.")
    # 1. pasted solid rectangles
    rects = []
    for c in np.unique(g):
        for comp in components(g == c):
            y0, x0, y1, x1 = bbox(comp)
            h, w = y1 - y0 + 1, x1 - x0 + 1
            if h >= 2 and w >= 2 and len(comp) == h * w and len(comp) >= 4:
                rects.append((len(comp), (y0, x0, y1, x1)))
    mask = np.zeros_like(g, dtype=bool)
    for _, (y0, x0, y1, x1) in rects:
        mask[y0:y1 + 1, x0:x1 + 1] = True
    # 2. find wallpaper period from uncovered cells
    best = None
    for py in range(1, H + 1):
        for px in range(1, W + 1):
            table = {}
            ok = True
            for y in range(H):
                for x in range(W):
                    if mask[y, x]:
                        continue
                    k = (y % py, x % px)
                    v = table.setdefault(k, g[y, x])
                    if v != g[y, x]:
                        ok = False
                        break
                if not ok:
                    break
            if ok and len(table) == py * px:
                best = (py, px, table)
                break
        if best:
            break
    py, px, table = best
    # 3. repair
    rep = g.copy()
    for y in range(H):
        for x in range(W):
            if mask[y, x]:
                rep[y, x] = table[(y % py, x % px)]
    emit(rep, f"Wallpaper period {py}x{px} found; every pasted rectangle is repaired from it.")
    # 4. crop under the largest rectangle
    rects.sort(key=lambda r: -r[0])
    y0, x0, y1, x1 = rects[0][1]
    out = rep[y0:y1 + 1, x0:x1 + 1].copy()
    emit(out, "Output: the restored pattern hidden under the largest rectangle.")
    return out
